from django.core.cache import cache
from django.db.models import Count, Avg


def get_book_stats():
    """آمار کلی کتاب‌ها را کش می‌کند."""
    key = "book_stats"
    data = cache.get(key)
    if data is None:
        data = {
            "total": Book.objects.count(),
            "by_category": list(
                Book.objects.values("category__name")
                .annotate(count=Count("id"))
                .order_by("-count")
            ),
            "avg_rating": Book.objects.aggregate(avg=Avg("rating"))["avg"],
        }
        cache.set(key, data, timeout=600)   # ۱۰ دقیقه
    return data


# الگوی cache-aside
def get_book(book_id):
    key = f"book:{book_id}"
    book = cache.get(key)
    if book is None:
        try:
            book = Book.objects.select_related("author").get(pk=book_id)
            cache.set(key, book, timeout=300)
        except Book.DoesNotExist:
            return None
    return book

