# Cache Stampede — استفاده از lock
from django.core.cache import cache
import time


def get_or_compute(key, compute_fn, timeout=300, lock_timeout=10):
    """جلوگیری از stampede با lock."""
    data = cache.get(key)
    if data is not None:
        return data

    lock_key = f"{key}:lock"
    if cache.add(lock_key, "1", timeout=lock_timeout):
        # ما lock گرفتیم — compute کن
        try:
            data = compute_fn()
            cache.set(key, data, timeout=timeout)
            return data
        finally:
            cache.delete(lock_key)
    else:
        # یکی دیگر compute می‌کند — صبر کن
        for _ in range(50):
            time.sleep(0.1)
            data = cache.get(key)
            if data is not None:
                return data
        # timeout — خودمان compute می‌کنیم
        return compute_fn()

# پیاده‌سازی در View
class PopularBooksView(APIView):
    def get(self, request):
        data = get_or_compute(
            "popular_books",
            lambda: list(Book.objects.filter(is_popular=True)[:20].values()),
            timeout=600,
        )
        return Response(data)

