# services.py
from django.core.cache import cache
from django.db.models import Count
from .models import Book

POPULAR_KEY = "books_popular"


def get_popular_books():
    def compute():
        return list(
            Book.objects
            .filter(is_active=True)
            .annotate(reviews_count=Count("reviews"))
            .order_by("-reviews_count")[:20]
            .values("id", "title", "price", "reviews_count")
        )

    return cache.get_or_set(POPULAR_KEY, compute, timeout=600)


def invalidate_popular_books():
    cache.delete(POPULAR_KEY)


# signals.py
